    /**
     * Storno z detailu objednavky (2026).
     *
     * Stornuje novy e-shop (CancelOrder): hlida stav, u zaplacene objednavky
     * zaznamena castku k vraceni a uvolni rezervace ve skladu. Penize vraci
     * obchod rucne, platebni brana neni.
     */
    public function cancelAction()
    {
        global $db;
        legacy_db();
        auth_require('obchod');
        if (is_post()) {
            csrf_check();
        }

        $id = get_param('id');
        $order = $db->one("SELECT * FROM orders WHERE id = " . $db->quote($id));
        if ($order === null) {
            return $this->notFound('Objednávka ' . $id . ' neexistuje');
        }
        if (!is_post()) {
            return $this->redirect(admin_url('order', array('id' => $id)));
        }
        if ($order['status'] == 'cancelled') {
            flash('Objednávka už je stornovaná', 'error');

            return $this->detailAction();
        }

        try {
            legacy_command(new \App\Ordering\Application\Command\CancelOrder(
                \App\Ordering\Domain\ValueObject\OrderId::fromString($id),
                trim((string) $this->post('reason'))
            ));
        } catch (\App\Ordering\Domain\Exception\InvalidOrderStateTransitionException $e) {
            flash('Odeslanou ani doručenou objednávku stornovat nejde', 'error');

            return $this->detailAction();
        }

        $cancelled = $db->one("SELECT refund_amount_in_cents, refund_currency FROM orders WHERE id = " . $db->quote($id));
        $refund = (int) $cancelled['refund_amount_in_cents'];
        audit_log('order', $id, 'storno', array('from' => $order['status'], 'refund' => $refund));
        cache_delete('dashboard_stats');

        if ($refund > 0) {
            flash('Objednávka stornována. Vraťte zákazníkovi ' . format_price($refund, $cancelled['refund_currency']));
        } else {
            flash('Objednávka stornována');
        }

        return $this->detailAction();
    }
}

